INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66390374', 66390374, 'analyze_legacy', 'Kab. Rokan Hulu', 'kabkota', 'RSUD Kabupaten Rokan Hulu', 'Biaya Jasa Konsultansi (Penyusunan Dokumen AMDAL)/DELH.', 'Jasa Konsultansi', 'Dikecualikan', 'Riau, Rokan Hulu (Kab.)', 500000000, 'March 2026', 'BLUD', 1, 0, '1 Paket', 'Secara administratif dan teknis, konsultan wajib menyusun dokumen yang terdiri dari beberapa pilar utama sesuai regulasi (di Indonesia saat ini Penyusunan DELH RSUD Rokan Hulu dimaksudkan untuk mengevaluasi kesesuaian kegiatan yang telah berjalan terhadap ketentuan lingkungan hidup, mengidentifikasi potensi dampak penting terhadap lingkungan, serta merumuskan upaya pengelolaan dan pemantauan lingkungan hidup yang diperlukan. Dokumen DELH ini juga menjadi dasar bagi pemerintah daerah dalam melakukan pengendalian dampak lingkungan serta sebagai pedoman bagi pengelola RSUD dalam melaksanakan kewajiban perlindungan dan pengelolaan lingkungan hidup secara berkelanjutan.', 'Keluaran Penyusunan DELH RSUD Rokan Hulu lengkap dan terinci sedemikian rupa sehingga tercapai penyesuaian terhadap tingkat optimum dari investasi serta pentahapan pelaksanaan dalam batas-batas kemampuan pembiayaan sehingga diperoleh hasil pekerjaan berupa: Dokumen DELH yang terdiri dari laporan pendahuluan, Konsep Dokumen DELH, Dokumen DELH. Dokumen Lelang, Kerangka Acuan Kerja, dan Softcopy Dokumen (Flashdisk) yang sesuai dengan standar yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2702341);
