INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66392126', 66392126, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693564 BALAI PENGELOLAAN DAERAH ALIRAN SUNGAI DODOKAN MOYOSARI', 'Pengadaan Media tanam (cocopeat, kompos dan sekam) dan Pengadaan Polybag (Pembuatan Bibit Vegetatif)', 'Barang', 'Pengadaan Langsung', 'Nusa Tenggara Barat, Lombok Tengah (Kab.)', 106325000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Pengadaan Media tanam (cocopeat, kompos dan sekam) dan Pengadaan Polybag (Kegiatan Pembuatan Bibit Besar) sebanyak satu paket kegiatan berupa Kompos/Pupuk Kandang 57.148 kg, Cocopeat 20.096 kg, Sekam 3.140 kg, Kantong Plastik (20 x 20 cm) 167 kg', 'Kompos/ Pupuk Kandang - Kompos atau pupuk kandang yang telah matang atau terfermentasi dengan baik. - Berwarna coklat tua hingga hitam. - Bertekstur remah dan tidak menggumpal. - Tidak berbau menyengat. - Bebas dari sampah anorganik seperti plastik, logam, kaca, dan sejenisnya. - Bebas dari hama, penyakit tanaman, serta biji gulma. - Tidak tercampur tanah atau bahan lain yang menurunkan kualitas media tanam. - Digunakan sebagai komponen utama media tanam dalam kegiatan pembibitan besar. Cocopeat - Berasal dari serbuk sabut kelapa yang telah diolah dan diayak. - Bertekstur halus dan ringan. - Bersih dari pasir, tanah, dan kotoran lainnya. - Memiliki kemampuan menyimpan air dengan baik. - Tidak mengandung bahan kimia berbahaya. - Tidak berbau menyengat. - Digunakan sebagai campuran media tanam untuk menjaga kelembaban media pembibitan. Sekam - Sekam padi kering atau sekam bakar. - Bersih dari tanah, batu, dan kotoran lainnya. - Memiliki tekstur ringan dan porous. - Tidak mengandung bahan berbahaya. - Berfungsi untuk meningkatkan aerasi dan drainase media tanam. - Digunakan sebagai campuran media tanam pada kegiatan pembibitan. Kantong Plastik (35x35cm) - Terbuat dari plastik jenis PE atau HDPE. - Warna hitam. - Ukuran ± 20 x 20 cm. - Ketebalan minimal 0,05 mm. - Memiliki lubang drainase pada bagian bawah atau samping. - Tahan terhadap penggunaan di area persemaian. - Digunakan sebagai wadah media tanam untuk kegiatan pembibitan vegetatif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2705656);
