INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66355698', 66355698, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'PCO Kampanye Indonesian Night (Doha, Qatar)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1652702000, 'September 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Paket, @ 1652702000 )', '1. PCO Kampanye Indonesian Night (Doha, Qatar) ( 1, Paket, @ 1652702000 );', 'Spesifikasi Pekerjaan Kegiatan Social Event – Cocktail Party (Pencalonan Indonesia pada ITU PP-26) 1. Penyediaan Venue dan Paket Meeting Menyediakan ballroom hotel bintang 5 untuk ±500 peserta selama 1 hari dengan konsep cocktail party/roundtable, termasuk konsumsi makanan Indonesia dan internasional, minuman, serta dukungan teknis dan keamanan dasar dari venue. 2 .Backdrop dan Panggung Pengadaan backdrop ukuran ±4 × 10 meter dengan desain full color, rangka dan pencahayaan, termasuk panggung, podium, instalasi, serta pembongkaran. 3. Sound System Penyediaan sistem audio standar acara kenegaraan (minimal 10.000 watt) lengkap dengan speaker, mixer, mikrofon wireless, kabel, operator, dan teknisi selama acara. 4. Lighting Panggung Pengadaan perangkat pencahayaan panggung seperti moving beam, PAR LED, mixer lighting, dan efek panggung untuk mendukung suasana acara. 5. Pengisi Acara / Music Performance Menyediakan penampil musik berpengalaman internasional, termasuk biaya perjalanan, akomodasi, honorarium, dan konsep pertunjukan yang disetujui panitia. 6. Bahan Promosi Pejabat Penyediaan souvenir premium untuk kegiatan bilateral meeting pejabat (misalnya teh premium dalam kemasan eksklusif). 7. Souvenir Peserta Social Event Pengadaan souvenir umum untuk sekitar 500 peserta acara. 8. Dokumentasi Acara Penyediaan layanan dokumentasi foto dan video lengkap dengan peralatan, editing, album foto, dan media penyimpanan digital. 9. Media Promosi Pengadaan rolling standing banner berdesain resmi untuk kebutuhan promosi acara. 10. Kendaraan Operasional Penyediaan kendaraan minivan operasional lengkap dengan sopir, bahan bakar, dan dukungan operasional selama kegiatan. 11. Pengiriman Kargo Layanan pengiriman barang kebutuhan acara secara door-to-door, termasuk packing, pengiriman, dan pengembalian barang. 12. Tenaga Event Organizer / PCO Penyediaan tenaga profesional event organizer untuk membantu penyelenggaraan acara di lokasi. 13. Pelaporan Kegiatan Penyusunan laporan kegiatan dalam bentuk hardcopy dan softcopy beserta dokumentasi lengkap.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2706011);
